using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using ParkingLotEnvironment.Training;

namespace ParkingLotEnvironment.CloudPilot {
public static class RefinementBuilder {
 public const string W="Assets/ParkingLotEnvironment/CloudPilot/ParkingRefinement20261105";
 static Transform holder; static Material white,concrete,cap,dark,blue,yellow;
 static readonly List<string> notes=new List<string>();
 static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rr.Length==0)throw new Exception("No geometry "+g.name);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static Material Mat(string name,Color color,float smooth=.2f){var m=new Material(Shader.Find("Standard")){name=name,color=color};m.SetFloat("_Glossiness",smooth);AssetDatabase.CreateAsset(m,W+"/"+name+".mat");return m;}
 static void Static(GameObject g){GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.ContributeGI|StaticEditorFlags.ReflectionProbeStatic);}
 static GameObject Box(string name,Vector3 p,Vector3 size,Material mat,bool collision=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(holder,false);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collision)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());Static(g);return g;}
 static void Line(string name,Vector3 a,Vector3 b,Material material,float width=.08f){var d=b-a;var g=Box(name,(a+b)*.5f,new Vector3(width,.0015f,d.magnitude),material,false);g.transform.rotation=Quaternion.LookRotation(d);g.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;}
 static void Paint(float ax,float az,float bx,float bz){Line("UniformParkingLine",new Vector3(ax,.004f,az),new Vector3(bx,.004f,bz),white);}
 static void Wall(Vector3 a,Vector3 b){float distance=Vector3.Distance(a,b);int count=Mathf.CeilToInt(distance/2.8f);var dir=(b-a).normalized;for(int i=0;i<count;i++){float len=distance/count;var p=Vector3.Lerp(a,b,(i+.5f)/count);var g=Box("ConcreteBoundaryPanel",p+Vector3.up*1.0f,new Vector3(.24f,2f,len-.012f),concrete);g.transform.rotation=Quaternion.LookRotation(dir);var c=Box("ConcreteWallCap",p+Vector3.up*2.055f,new Vector3(.32f,.11f,len-.014f),cap,false);c.transform.rotation=g.transform.rotation;var foot=Box("ConcreteWallBase",p+Vector3.up*.12f,new Vector3(.26f,.24f,len-.012f),dark,false);foot.transform.rotation=g.transform.rotation;}}
 static void Panel(string name,Vector3 p,Vector2 size,string texture,bool reverse=false){var frame=Box(name+"Frame",p,new Vector3(size.x+.06f,size.y+.06f,.07f),dark,false);var g=GameObject.CreatePrimitive(PrimitiveType.Quad);g.name=name;g.transform.SetParent(holder,false);g.transform.position=p+Vector3.back*.042f;g.transform.localScale=new Vector3(size.x,size.y,1);UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());var mat=Mat(name+"Material",Color.white,.1f);mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(W+"/"+texture);g.GetComponent<Renderer>().sharedMaterial=mat;Static(g);if(reverse){var back=UnityEngine.Object.Instantiate(g,holder);back.name=name+"Inside";back.transform.position=p+Vector3.forward*.042f;back.transform.rotation=Quaternion.Euler(0,180,0);}}
 static void Arrow(float x,float z,bool inward){float sign=inward?1:-1;Line("EntryExitArrowShaft",new Vector3(x,.004f,z-sign*.65f),new Vector3(x,.004f,z+sign*.35f),white,.17f);Line("EntryExitArrowHead",new Vector3(x-.43f,.004f,z),new Vector3(x,.004f,z+sign*.55f),white,.17f);Line("EntryExitArrowHead",new Vector3(x+.43f,.004f,z),new Vector3(x,.004f,z+sign*.55f),white,.17f);}
 static void Apron(GameObject root){var source=root.transform.Find("Zone_Asphalt/default");var mesh=new Mesh{name="FlushEntranceApron",vertices=new[]{new Vector3(-9.45f,-.006f,-26),new Vector3(-9.45f,-.006f,-20),new Vector3(9.45f,-.006f,-20),new Vector3(9.45f,-.006f,-26)},triangles=new[]{0,1,2,0,2,3},uv=new[]{new Vector2(-9.45f/30,-26f/30),new Vector2(-9.45f/30,-20f/30),new Vector2(9.45f/30,-20f/30),new Vector2(9.45f/30,-26f/30)}};mesh.RecalculateNormals();mesh.RecalculateTangents();Unwrapping.GenerateSecondaryUVSet(mesh);AssetDatabase.CreateAsset(mesh,W+"/EntranceApron.asset");var go=new GameObject("EntranceFlushApron");go.transform.SetParent(holder,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=source.GetComponent<Renderer>().sharedMaterial;go.AddComponent<MeshCollider>().sharedMesh=mesh;Static(go);}
 static bool Body(Material m){if(!m)return false;string n=m.name.ToLowerInvariant();return n.Contains("_i30_")||n.Contains("_tucson0_")||n.Contains("_tucson5_")||n.Contains("_azera3_")||n.Contains("_azera6_");}
 static void Recolor(GameObject vehicle,string colorName,Color color){var clones=new Dictionary<Material,Material>();int count=0;foreach(var r in vehicle.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var old=mats[i];if(!Body(old))continue;if(!clones.TryGetValue(old,out var m)){m=new Material(old){name=vehicle.name+"_"+colorName+"_"+clones.Count};m.color=color;m.SetFloat("_Glossiness",.83f);m.SetFloat("_Metallic",.28f);AssetDatabase.CreateAsset(m,W+"/"+m.name+".mat");clones.Add(old,m);}mats[i]=m;count++;}r.sharedMaterials=mats;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;r.receiveShadows=true;}if(count==0)throw new Exception("Body material not found for "+vehicle.name);notes.Add(vehicle.name+" -> "+colorName+" ("+count+" body slots)");}
 static void BlueTruck(GameObject truck){var dict=new Dictionary<Material,Material>();int count=0;foreach(var r in truck.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var old=mats[i];if(!old||old.shader.name!="Standard")continue;var c=old.color;string n=old.name.ToLowerInvariant();bool cargo=r.name.StartsWith("Cargo");if(!cargo&&(c.grayscale<.38f||n.Contains("tire")||n.Contains("chrome")||n.Contains("glass")||n.Contains("lamp")))continue;if(!dict.TryGetValue(old,out var m)){m=new Material(old){name=truck.name+"_CommercialBlue_"+dict.Count};m.color=new Color(.018f,.13f,.39f);m.mainTexture=null;m.SetFloat("_Glossiness",.66f);m.SetFloat("_Metallic",.2f);AssetDatabase.CreateAsset(m,W+"/"+m.name+".mat");dict.Add(old,m);}mats[i]=m;count++;}r.sharedMaterials=mats;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;}notes.Add(truck.name+" blue repaint slots="+count+"; generic cab-over remains, NOT a Hyundai Porter/Bongo licensed mesh.");}
 public static void Apply(GameObject root,string output){
  var layout=root.GetComponentInChildren<ParkingTrainingLayout>();if(!layout)throw new Exception("Training layout missing");var previous=layout.transform;
  holder=new GameObject("ParkingRefinement_EntranceAndBoundary").transform;holder.SetParent(root.transform,false);
  white=Mat("ConsistentWhiteParkingPaint",new Color(.83f,.83f,.79f),.08f);dark=Mat("WeatheredConcreteBase",new Color(.24f,.255f,.25f),.12f);cap=Mat("ConcreteCoping",new Color(.49f,.49f,.465f),.15f);blue=Mat("GateBlueMetal",new Color(.035f,.13f,.28f),.5f);yellow=Mat("GateSafetyYellow",new Color(.68f,.43f,.055f),.2f);
  var shader=Shader.Find("ParkingLot/Refinement20261105/Concrete");if(!shader)throw new Exception("Concrete shader missing");concrete=new Material(shader){name="CastConcreteBoundary",color=new Color(.58f,.58f,.55f)};AssetDatabase.CreateAsset(concrete,W+"/CastConcreteBoundary.mat");
  foreach(var t in previous.GetComponentsInChildren<Transform>().Where(t=>t.name=="ParkingLine").ToArray())t.gameObject.SetActive(false);
  // One shared separator for adjacent bays; every bay is open toward the driving aisle.
  Paint(-8.3f,-18,-8.3f,12);for(int i=0;i<=10;i++)Paint(-8.3f,-18+3*i,-2.9f,-18+3*i);
  Paint(8,-19,8,13);foreach(float z in new[]{-19f,-14f,-5.6f,-.4f,8f,13f})Paint(5.4f,z,8,z);
  foreach(var bay in layout.bays){if(bay.maneuver==ParkingManeuver.ReversePerpendicular)bay.width=3f;else bay.length=8.4f;}
  var context=root.transform.Find("DaylightPass_Context");var oldTruck=context.Find("Daylight_ProvisionalTruck");if(oldTruck)oldTruck.gameObject.SetActive(false);
  Recolor(previous.Find("Parked_T_0").gameObject,"Black",new Color(.035f,.044f,.055f));
  Recolor(previous.Find("Parked_T_1").gameObject,"PearlWhite",new Color(.79f,.80f,.81f));
  Recolor(previous.Find("Parked_T_3").gameObject,"DeepNavy",new Color(.028f,.07f,.145f));
  Recolor(previous.Find("Parked_T_6").gameObject,"Burgundy",new Color(.25f,.025f,.045f));
  Recolor(previous.Find("Parked_T_8").gameObject,"Graphite",new Color(.12f,.14f,.16f));
  Recolor(previous.Find("Parked_T_9").gameObject,"Silver",new Color(.55f,.58f,.60f));
  Recolor(previous.Find("Parked_P_Front").gameObject,"SapphireBlue",new Color(.025f,.15f,.34f));
  Recolor(previous.Find("Parked_P_Rear").gameObject,"Black",new Color(.035f,.044f,.055f));
  var cargo=previous.Find("Parked_T_4").gameObject;BlueTruck(cargo);BlueTruck(previous.Find("Parked_P_BoxTruck").gameObject);
  // Remove the obsolete tall box-truck front bulkhead left behind by the earlier flatbed conversion.
  foreach(var f in cargo.GetComponentsInChildren<MeshFilter>()){var src=f.sharedMesh;if(!src||!src.isReadable||src.subMeshCount!=1||f.name.StartsWith("Cargo"))continue;var vv=src.vertices;var tt=src.triangles;var keep=new List<int>();for(int i=0;i<tt.Length;i+=3){var a=f.transform.TransformPoint(vv[tt[i]]);var b=f.transform.TransformPoint(vv[tt[i+1]]);var c=f.transform.TransformPoint(vv[tt[i+2]]);var mid=(a+b+c)/3;if(mid.y>2.08f)continue;keep.AddRange(new[]{tt[i],tt[i+1],tt[i+2]});}if(keep.Count==tt.Length)continue;if(keep.Count==0){f.GetComponent<Renderer>().enabled=false;continue;}var mesh=UnityEngine.Object.Instantiate(src);mesh.name="LoweredCargo_"+src.name;mesh.triangles=keep.ToArray();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(W+"/"+mesh.name+".asset"));f.sharedMesh=mesh;}
  foreach(var o in layout.obstacles){var g=previous.Find(o.id).gameObject;var b=BoundsOf(g);o.center=b.center;o.size=b.size;var collider=g.GetComponent<BoxCollider>();collider.center=g.transform.InverseTransformPoint(b.center);collider.size=b.size;if(o.id=="Parked_T_4"){o.category="Generic blue light cargo truck";o.model="Existing generic cab-over; exact Porter/Bongo pending";}}
  layout.truckModelNote="Blue generic light cargo and delivery trucks. Exact Hyundai Porter/Kia Bongo mesh is not yet available; not represented as an OEM model.";
  Wall(new Vector3(-9.3f,0,-20.4f),new Vector3(-9.3f,0,14.55f));Wall(new Vector3(9.3f,0,-20.4f),new Vector3(9.3f,0,14.55f));Wall(new Vector3(-9.3f,0,14.55f),new Vector3(9.3f,0,14.55f));
  // Seven metres of unobstructed, overhead-free entry between the inner faces of the pillars.
  Wall(new Vector3(-9.3f,0,-20.4f),new Vector3(-3.1f,0,-20.4f));Wall(new Vector3(4.5f,0,-20.4f),new Vector3(9.3f,0,-20.4f));
  foreach(float x in new[]{-3.1f,4.5f}){Box("EntrancePillar",new Vector3(x,1.14f,-20.4f),new Vector3(.6f,2.28f,.6f),concrete);Box("PillarCap",new Vector3(x,2.32f,-20.4f),new Vector3(.68f,.08f,.68f),cap,false);Box("GateReflectiveStrip",new Vector3(x,.82f,-20.711f),new Vector3(.3f,.55f,.012f),yellow,false);}
  Apron(root);for(float z=-25.3f;z< -20.5f;z+=1.45f)Line("EntranceCenterDashes",new Vector3(.7f,.004f,z),new Vector3(.7f,.004f,z+.7f),yellow,.1f);
  Arrow(2.45f,-23.1f,true);Arrow(-1.05f,-23.1f,false);
  // Signs sit on the wall, outside the gate clearance. No barrier arm or collider spans the opening.
  Panel("ParkingEntranceSign",new Vector3(6.65f,2.65f,-20.46f),new Vector2(2.6f,1.2f),"EntranceSign.png",true);
  Box("EntranceSignPost",new Vector3(6.65f,1.28f,-20.35f),new Vector3(.09f,2.56f,.09f),blue);
  Panel("EntryDirection",new Vector3(4.5f,1.53f,-20.72f),new Vector2(.45f,.55f),"Entry.png");Panel("ExitDirection",new Vector3(-3.1f,1.53f,-20.72f),new Vector2(.45f,.55f),"Exit.png");
  foreach(string id in new[]{"TrainingSignFrame_T","TrainingSignFace_T","TrainingSignPost_T"}){var t=previous.Find(id);if(t)t.position+=new Vector3(.45f,.6f,0);}foreach(string id in new[]{"TrainingSignFrame_P","TrainingSignFace_P","TrainingSignPost_P"}){var t=previous.Find(id);if(t)t.position+=new Vector3(-.45f,.6f,0);}
  layout.entrySpawn.position=new Vector3(2.45f,0,-23);EditorUtility.SetDirty(layout);Physics.SyncTransforms();File.WriteAllText(output+"/layout.json",JsonUtility.ToJson(layout,true));notes.Add("Concrete boundary: height 2m; entrance clear width 7m, open overhead; flush 6m entrance apron, entry/exit arrows and signs. Perpendicular shared 3m separators and open-aisle paint; parallel open-aisle bays.");File.WriteAllLines(output+"/build-notes.txt",notes);
 }
 public static void Validate(GameObject root,string output){TrainingValidation.Check(root,output);Physics.SyncTransforms();int samples=0;foreach(float x in new[]{-1.05f,2.45f})for(float z=-25;z<=-18;z+=.5f){var center=new Vector3(x,1.38f,z);var hits=Physics.OverlapBox(center,new Vector3(1.1f,1.35f,2.575f),Quaternion.identity,~0,QueryTriggerInteraction.Ignore);if(hits.Length>0)throw new Exception("Entrance obstruction at "+center+": "+string.Join(",",hits.Select(c=>c.name)));RaycastHit h;if(!Physics.Raycast(new Vector3(x,1,z),Vector3.down,out h,2)||Mathf.Abs(h.point.y)>.045f)throw new Exception("Entrance floor discontinuity");samples++;}File.AppendAllText(output+"/map-validation.txt","Entrance swept rectangular vehicle 5.15m x 2.2m x 2.7m, both lanes: "+samples+" clear samples; 7m clear gate opening and flush pavement.\n");}
}}
